LITERALS = json.loads(r'''[35540916, 35541388, 35541660, 35542136, 35542140, 35542144, 35542148, 35542152, 35542156, 35542160, 35542164, 35543292, 35543444, 35543448, 35543452, 35543768, 35543772, 35543924, 35544168, 35544280, 35544288, 35547636, 35547960, 35548184, 35548188, 35548372, 35548740, 35548884, 35548892, 35549276, 35549280, 35549284, 35549288, 35549292, 35549296, 35549572, 35549668, 35549672, 35550136, 35550488, 35550896, 35551100, 35551320, 35551332, 35551476, 35551548, 35551712, 35551860, 35552112, 35552456, 35552580, 35552988, 35553292, 35553656, 35554248, 35554476, 35554636, 35554896, 35555260, 35556112, 35556376, 35556380, 35556448, 35556532, 35556728, 35556916, 35557220, 35557376, 35558100, 35558104, 35558424, 35558532, 35559824, 35559952, 35560724, 35560820]''')             # literal-pool words holding pointers

def enc_bl(at, target, blx):
    pc = at + 4
    if blx:
        pc &= ~3
        assert target % 4 == 0
    off = target - pc
    assert -0x400000 <= off < 0x400000, hex(off)
    hi = 0xF000 | ((off >> 12) & 0x7FF)
    lo = (0xE800 if blx else 0xF800) | ((off >> 1) & 0x7FF)
    return struct.pack('<HH', hi, lo)

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('ov077')
    ap.add_argument('--bank', type=int, default=854)
    ap.add_argument('--out', default='build/slots_jp_blob.bin')
    ap.add_argument('--us-arm9'); ap.add_argument('--jp-arm9')
    a = ap.parse_args()
    d = bytearray(open(a.ov077, 'rb').read())
    if len(d) != SIZE:
        sys.exit('ov077.bin is %d bytes, expected %d (decompressed Japanese HeartGold rev 0)' % (len(d), SIZE))
    if hashlib.sha1(d).hexdigest() != '5e84032fa7f12905dba5bd6358bf0080b22e3e41':
        print('warning: ov077.bin differs from the copy this script was made for; check the results')
    delta = NEW_BASE - OLD_BASE
    def put(addr, b):
        o = addr - OLD_BASE; d[o:o+len(b)] = b
    def word(addr):
        return struct.unpack_from('<I', d, addr - OLD_BASE)[0]
    # 1. calls into the main program
    for at, kind, jp in BL_SITES:
        us = int(CALLS[hex(jp)][1], 16)
        put(at, enc_bl(at + delta, us, kind == 'blx'))
    # 2. literal-pool pointers
    for at in LITERALS:
        w = word(at)
        if OLD_BASE <= w < OLD_BASE + SIZE:
            nw = w + delta
        elif w in POINTERS:
            nw = POINTERS[w]
        else:
            sys.exit('unexpected literal %08X at %08X' % (w, at))
        put(at, struct.pack('<I', nw))
    # 3. function tables
    for start, n in FUNC_TABLES:
        for k in range(n):
            w = word(start + 4*k)
            assert OLD_BASE <= w < OLD_BASE + SIZE, hex(w)
            put(start + 4*k, struct.pack('<I', w + delta))
    # 4. text bank
    assert word(TEXT_BANK_LITERAL) == 429
    put(TEXT_BANK_LITERAL, struct.pack('<I', a.bank))
    # optional check against the user's ROMs
    if a.us_arm9 and a.jp_arm9:
        check(open(a.us_arm9, 'rb').read(), open(a.jp_arm9, 'rb').read())
    os.makedirs(os.path.dirname(a.out) or '.', exist_ok=True)
    open(a.out, 'wb').write(d)
    print('wrote %s (%d bytes), %d calls, %d pointers, text bank %d' % (a.out, len(d), len(BL_SITES), len(LITERALS), a.bank))

def check(us, jp):
    """Check every mapped address against your ROMs before patching anything.
    Functions from pret/pokeheartgold are compared with their known US bytes; SDK/runtime
    functions are compared with the Japanese copy (branch offsets and pointers masked)."""
    B = 0x02000000
    if len(us) < 0xB0000:
        sys.exit('US arm9.bin looks compressed; use hg-engine base/arm9.bin after one make')
    bad = 0
    for jpa, (name, usa) in sorted(CALLS.items()):
        u = (int(usa, 16) & ~1) - B
        if name in US_SIGS:
            h = US_SIGS[name]
            ok = all(h[2*i:2*i+2] == '??' or us[u+i] == int(h[2*i:2*i+2], 16) for i in range(len(h)//2))
        else:
            j = (int(jpa, 16) & ~1) - B
            ok = True
            for i in range(0, 32, 4):
                a = jp[j+i:j+i+4]; b = us[u+i:u+i+4]
                if a == b or (a[3] in (0xEA, 0xEB, 0xFA, 0xFB, 0x0A, 0x1A) and a[3] == b[3]) or a[3] == 0x02:
                    continue
                ok = False; break
        if not ok:
            bad += 1
            print('MISMATCH %-40s US %s' % (name, usa))
    print('address check: %d of %d functions OK' % (len(CALLS) - bad, len(CALLS)))
    if bad:
        sys.exit('stopping: send these MISMATCH lines back')

if __name__ == '__main__':
    main()
